pub unsafe extern "C" fn xmlFileClose(mut context: *mut c_void) -> c_int {
    let mut fil: *mut FILE = ::core::ptr::null_mut::<FILE>();
    let mut ret: c_int = 0;
    if context.is_null() {
        return -(1 as c_int);
    }
    fil = context as *mut FILE;
    if fil == stdout || fil == stderr {
        ret = fflush(fil);
        if ret < 0 as c_int {
            xmlIOErr(
                0 as c_int,
                b"fflush()\0" as *const u8 as *const c_char,
            );
        }
        return 0 as c_int;
    }
    if fil == stdin {
        return 0 as c_int;
    }
    ret = if fclose(context as *mut FILE) == EOF {
        -(1 as c_int)
    } else {
        0 as c_int
    };
    if ret < 0 as c_int {
        xmlIOErr(
            0 as c_int,
            b"fclose()\0" as *const u8 as *const c_char,
        );
    }
    return ret;
}
